from collections import defaultdict, deque
class Solution:
    def countPalindromePaths(self, parent: List[int], s: str) -> int:
        n = len(parent)
        ch = defaultdict(list)
        for i in range(1, n): ch[parent[i]].append(i)
        mask = [0] * n
        order = []
        dq = deque([0])
        while dq:
            u = dq.popleft(); order.append(u)
            for v in ch[u]:
                mask[v] = mask[u] ^ (1 << (ord(s[v]) - 97))
                dq.append(v)
        cnt = defaultdict(int); ans = 0
        for u in order:
            m = mask[u]
            if u != 0:
                ans += cnt[m]
                for b in range(26): ans += cnt[m ^ (1 << b)]
            cnt[m] += 1
        return ans

