class Solution {
public:
    long long countPalindromePaths(vector<int>& parent, string s) {
        int n = parent.size();
        vector<vector<int>> ch(n);
        for (int i = 1; i < n; i++) ch[parent[i]].push_back(i);
        vector<int> mask(n, 0), order;
        queue<int> q; q.push(0);
        while (!q.empty()) {
            int u = q.front(); q.pop(); order.push_back(u);
            for (int v : ch[u]) { mask[v] = mask[u] ^ (1 << (s[v] - 'a')); q.push(v); }
        }
        unordered_map<int, long long> cnt;
        long long ans = 0;
        for (int u : order) {
            int m = mask[u];
            if (u != 0) {
                auto it = cnt.find(m); if (it != cnt.end()) ans += it->second;
                for (int b = 0; b < 26; b++) {
                    auto it2 = cnt.find(m ^ (1 << b));
                    if (it2 != cnt.end()) ans += it2->second;
                }
            }
            cnt[m]++;
        }
        return ans;
    }
};

