class Solution {
    public long countPalindromePaths(int[] parent, String s) {
        int n = parent.length;
        List<List<Integer>> ch = new ArrayList<>();
        for (int i = 0; i < n; i++) ch.add(new ArrayList<>());
        for (int i = 1; i < n; i++) ch.get(parent[i]).add(i);
        int[] mask = new int[n];
        List<Integer> order = new ArrayList<>();
        Deque<Integer> q = new ArrayDeque<>(); q.add(0);
        while (!q.isEmpty()) {
            int u = q.poll(); order.add(u);
            for (int v : ch.get(u)) { mask[v] = mask[u] ^ (1 << (s.charAt(v) - 'a')); q.add(v); }
        }
        Map<Integer, Long> cnt = new HashMap<>();
        long ans = 0;
        for (int u : order) {
            int m = mask[u];
            if (u != 0) {
                ans += cnt.getOrDefault(m, 0L);
                for (int b = 0; b < 26; b++) ans += cnt.getOrDefault(m ^ (1 << b), 0L);
            }
            cnt.merge(m, 1L, Long::sum);
        }
        return ans;
    }
}

