class Solution:
    def countPalindromePaths(self, parent: List[int], s: str) -> int:
        n = len(parent)
        ch = defaultdict(list)
        for i in range(1, n): ch[parent[i]].append(i)
        mask = [0] * n
        dq = deque([0])
        while dq:
            u = dq.popleft()
            for v in ch[u]:
                mask[v] = mask[u] ^ (1 << (ord(s[v]) - 97))
                dq.append(v)
        cnt = defaultdict(int)
        for m in mask: cnt[m] += 1
        ans = sum(c * (c - 1) // 2 for c in cnt.values())
        cross = 0
        for m, c in cnt.items():
            for b in range(26):
                cross += c * cnt.get(m ^ (1 << b), 0)
        return ans + cross // 2

